select t.n, t.slug, t.field, t.rows_matched, t.text_ok
from (values
  (1, '8lements-spa-saranam', 'why_its_here', (select count(*)::int from venues where slug = '8lements-spa-saranam' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'f09788168065f2d4a6f34d0cfafc5c4c'), md5('A rooftop spa at HOMM Saranam in the Bedugul highlands, looking out over rice terraces and mountains. It runs under Banyan Group''s 8LEMENTS wellness brand, with therapists trained at the Banyan Tree Academy. Non-guests are welcome.') = '246d6029973e902fd455c902a0a4c4c0'),
  (2, '8lements-spa-saranam', 'best_for', (select count(*)::int from venues where slug = '8lements-spa-saranam' and status = 'active' and publication_status = 'published' and md5(best_for) = '6eef10a747ce54dbe4dd0e47cb78045f'), md5('A highland spa session with a rice-terrace view on a Bedugul or North Bali day trip') = '7bd178d4559732f42027314887121ba7'),
  (3, 'air-terjun-tegenungan', 'why_its_here', (select count(*)::int from venues where slug = 'air-terjun-tegenungan' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '38daf74879fc3e0b6873291f6d689f74'), md5('A big waterfall beside Tegenungan village in Gianyar, about 10 kilometres outside Ubud. It is easy to reach, and steps take you down to the falls.') = 'a239cea445fdc8116ab9621200c8527d'),
  (4, 'air-terjun-tegenungan', 'best_for', (select count(*)::int from venues where slug = 'air-terjun-tegenungan' and status = 'active' and publication_status = 'published' and md5(best_for) = 'f5cf5758e99cc708f6943558512dd5af'), md5('A waterfall stop near Ubud for anyone who wants falls without a trek') = '05528dee4dfb1c20fc5e1e9bbebfc949'),
  (5, 'akar-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'akar-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '020dd01a98f1249d009c43bf4281d75c'), md5('Akar is a jungle restaurant at Kedisan in Tegallalang, north of Ubud. It does breakfast and dinner, and the setting suits a special occasion.') = '6256637847b602975d359e9898e3d892'),
  (6, 'akar-ubud', 'best_for', (select count(*)::int from venues where slug = 'akar-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = '2ed7b0b87e59e632406c5f2710e4a071'), md5('A destination dinner with jungle views') = '57eb244c9a8c0f8294cd3e7aefac9be8'),
  (7, 'akar-ubud', 'not_for', (select count(*)::int from venues where slug = 'akar-ubud' and status = 'active' and publication_status = 'published' and md5(not_for) = '4cc16ea5fa081fa455bf869a3bc3b6a2'), md5('A walk-in lunch while you are in central Ubud, because it is out of town to the north') = 'e04ba15b16eb3b196731bc5d38e3f30f'),
  (8, 'alchemy', 'why_its_here', (select count(*)::int from venues where slug = 'alchemy' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'fce9f5e40276eac08d0e45542efbb1f6'), md5('Alchemy is a breakfast spot in Penestanan where the whole menu is plant-based and gluten-free. At the raw breakfast bar you choose what goes on your plate, and the prices are clear before you order.') = 'b07e6fcd1a9ce3a76840c46045aacd50'),
  (9, 'alchemy', 'best_for', (select count(*)::int from venues where slug = 'alchemy' and status = 'active' and publication_status = 'published' and md5(best_for) = '9ba1e51fc5bf529e5dcf36ee23616668'), md5('A plant-based, gluten-free meal, a breakfast after yoga, or laptop time off-peak') = '428914902621811942d725e002449c5a'),
  (10, 'alchemy-yoga-and-meditation-center-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'alchemy-yoga-and-meditation-center-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '2b623dedee3b5a69a0be34fb7adf1ad4'), md5('A Penestanan centre for yoga and meditation, with its roots in tantra and Hatha yoga. There is a full timetable of classes every day, plus meditation, sound healing and a weekly ecstatic-dance night. It is affiliated with the Alchemy raw-vegan cafe next door.') = 'dba7ba7e47cb5d580bf1bc56be643885'),
  (11, 'alchemy-yoga-and-meditation-center-ubud', 'best_for', (select count(*)::int from venues where slug = 'alchemy-yoga-and-meditation-center-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b1550d6ec41996d4f3d2994b95889f16'), md5('Practitioners drawn to tantra-influenced yoga and community events like ecstatic dance, with a plant-based meal next door') = 'fccadcce61770ab31be17d62c08b55ca'),
  (12, 'alchemy-yoga-meditation-center', 'why_its_here', (select count(*)::int from venues where slug = 'alchemy-yoga-meditation-center' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1cad7d7fe626957ec9dcfbb57bb2b762'), md5('This yoga and meditation centre in Penestanan teaches in two bamboo shalas. Drop-in classes run every day across Hatha and Tantra vinyasa, Yin, meditation, ecstatic dance and sound-healing ceremonies. There are multi-class passes and Yoga Alliance teacher trainings at 200hr and 300hr.') = '4e815785416c00b970841df200f6b340'),
  (13, 'alchemy-yoga-meditation-center', 'best_for', (select count(*)::int from venues where slug = 'alchemy-yoga-meditation-center' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c920b13bf599cc4597f7133bfafce1d7'), md5('Drop-in practitioners staying in Ubud or Penestanan who want a varied daily schedule without committing to a retreat') = '485020379e9211ac1a75f9e653d275fd'),
  (14, 'alchemy-yoga-meditation-center', 'not_for', (select count(*)::int from venues where slug = 'alchemy-yoga-meditation-center' and status = 'active' and publication_status = 'published' and md5(not_for) = '1a6266ff5ad05006a1f66561e5a551af'), md5('A gym-style fitness workout or a beach and nightlife scene. This is yoga and meditation in Penestanan') = '040c97826da2f80adbe146efe0ed29b3'),
  (15, 'anomali-coffee-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'anomali-coffee-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5392076d87ee75099518a61432292404'), md5(U&'The Jalan Raya Ubud caf\00E9 of Anomali, an Indonesian specialty-coffee roaster founded in Jakarta in 2007 that now has outlets across Indonesia. Its single-origin beans come from all over the archipelago, and the regions on offer rotate.') = 'df5427437eaeb460ed4a96fc29288bd6'),
  (16, 'anomali-coffee-ubud', 'best_for', (select count(*)::int from venues where slug = 'anomali-coffee-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = '72e0457f828c9d24e92a8b71002ca44b'), md5('Comparing single origins from Aceh, Bali, Toraja and Java in one sitting, or a casual all-day breakfast') = '260596c5f9c2c57e25ddd8d16dbac94c'),
  (17, 'anomali-coffee-ubud', 'not_for', (select count(*)::int from venues where slug = 'anomali-coffee-ubud' and status = 'active' and publication_status = 'published' and md5(not_for) = '679845a3c5c4ec9b3934bd4785fc4e20'), md5(U&'A jungle or rice-field view, because this is a street-front caf\00E9 in town') = '96bb0c5a7a485197f75b74829e01d280'),
  (18, 'bali-barber-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'bali-barber-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '483012d946108d1b6b6842d0de398729'), md5('Bali Barber''s shop in central Ubud, where men can walk in for a cut, beard work or a traditional hot-towel shave.') = '2c8612183c484dda732634d5e6d85fea'),
  (19, 'bali-barber-ubud', 'best_for', (select count(*)::int from venues where slug = 'bali-barber-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = 'dcdf518aefae8d5e560398e54a4579eb'), md5('A men''s cut or shave in central Ubud without booking ahead') = '91158e95e65f098c16511440ba456e4b'),
  (20, 'bali-bohemia', 'why_its_here', (select count(*)::int from venues where slug = 'bali-bohemia' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c09dfa7af96dde545e76038f3136005a'), md5('A boutique hotel''s restaurant and bakery beside the Sacred Monkey Forest Sanctuary. The cooking is East-Mediterranean in style and leans plant-forward. The bakery also runs on its own, and some evenings have live music.') = '406974cc819014a3c34e6ba7c4b18fe4'),
  (21, 'bali-bohemia', 'best_for', (select count(*)::int from venues where slug = 'bali-bohemia' and status = 'active' and publication_status = 'published' and md5(best_for) = 'dea07318b0d770d3fc9cd96a0404feef'), md5('A plant-forward breakfast, bakery pastries, or dinner with live music in a colourful, creative setting') = '340e783a4fe0631c76001f33011b617b'),
  (22, 'bali-bohemia', 'not_for', (select count(*)::int from venues where slug = 'bali-bohemia' and status = 'active' and publication_status = 'published' and md5(not_for) = 'c0aa57fe6a7105320727b20a574bbeb7'), md5('A strictly Balinese or Indonesian menu, or a quiet dinner: the food is East-Mediterranean and some evenings have live music') = '5d4dd1f26e13379f780f4d7547fae5e8'),
  (23, 'bali-botanica-spa', 'why_its_here', (select count(*)::int from venues where slug = 'bali-botanica-spa' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '9a39b8a0b18da6202d512a3c04dd188b'), md5('An Ayurvedic day spa on the Sanggingan ridge that looks over jungle and rice fields. It opened in 2006, and in 2024 it was relaunched under Oneworld Ayurveda with Balinese and Ayurvedic treatments and programs.') = '60cfd3bd8c1ad0a7de3326d9c58afeac'),
  (24, 'bali-botanica-spa', 'best_for', (select count(*)::int from venues where slug = 'bali-botanica-spa' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c0dcd18c3b3eb6b2f7052fc029d64abd'), md5('Ayurvedic treatments or a day program on the Sanggingan side of Ubud, with jungle and rice-field views') = '851b1bc7b9df9812211f53396477a055'),
  (25, 'bebek-bengil', 'why_its_here', (select count(*)::int from venues where slug = 'bebek-bengil' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '058a21dceb0305c7a27908d403a5d1c6'), md5('Bebek Bengil is a duck restaurant in Ubud, open since 1990, with dining pavilions in a rice-paddy garden. Its Balinese-style crispy duck is steamed in Indonesian spices, then deep-fried until the skin crackles and the meat stays tender.') = '88699ceba1ce55a435e4bced0941f014'),
  (26, 'bebek-bengil', 'best_for', (select count(*)::int from venues where slug = 'bebek-bengil' and status = 'active' and publication_status = 'published' and md5(best_for) = '241e665334e9d7c2fd2e5f9c391c96b6'), md5('A first taste of Balinese crispy duck, or a group dinner of shared regional dishes near the Monkey Forest') = '26b200982cc183d84c042d4ed38dc356'),
  (27, 'bebek-bengil', 'not_for', (select count(*)::int from venues where slug = 'bebek-bengil' and status = 'active' and publication_status = 'published' and md5(not_for) = 'c8368e04a6cdb6ad71163c98668a66a4'), md5('Vegetarians, since the menu centres on duck and meat, or anyone looking for a quiet local warung') = '2ac87e58feee11fae69c65a753c91b41'),
  (28, 'big-dragon-villas-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'big-dragon-villas-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c66e6320952728554bc97e9cac29f81b'), md5('A boutique villa property in the rice paddies at Pejeng, near Tampaksiring, opened in 2025. Its 17 rooms and suites sit around an infinity pool, and central Ubud is a short drive away.') = '13951eac4a273bb4b7706f4c858780cf'),
  (29, 'big-dragon-villas-ubud', 'best_for', (select count(*)::int from venues where slug = 'big-dragon-villas-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = '83a791f235608e19f60c76b049f2e8a4'), md5('A quiet stay away from the centre of Ubud, with views over the pool and rice fields') = '8fa7343e4630e62a54344970d31adcae'),
  (30, 'cafe-wayan-and-bakery', 'why_its_here', (select count(*)::int from venues where slug = 'cafe-wayan-and-bakery' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ec56952def3a5bb855086fc972a37608'), md5('Open since 1986 on Monkey Forest Road, this restaurant has a bakery out front and a garden behind that looks over rice paddies. The menu is wide, running across Indonesian, Thai and Italian, and Sunday evenings bring a traditional Balinese buffet.') = '8e80631a5f4af808a9f850a2aa95b614'),
  (31, 'cafe-wayan-and-bakery', 'best_for', (select count(*)::int from venues where slug = 'cafe-wayan-and-bakery' and status = 'active' and publication_status = 'published' and md5(best_for) = '452c8bae16647564f8cf6ea57aaa86ae'), md5('Groups or families after a garden meal with a broad menu and a dessert to share') = '786f1b40eee4a5584cd43a4fcd49d1ac'),
  (32, 'cafe-wayan-and-bakery', 'not_for', (select count(*)::int from venues where slug = 'cafe-wayan-and-bakery' and status = 'active' and publication_status = 'published' and md5(not_for) = '07a3e54cae8c335b734eb4a6c0e66644'), md5('A quiet, intimate table: it is a large place with a fast turnover of tourists') = '46242d73216de9477d9fe6335de7fffa'),
  (33, 'cantika-zest', 'why_its_here', (select count(*)::int from venues where slug = 'cantika-zest' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1c783e77c9ea5cdff621bf7c3642ea01'), md5('A jungle spa beside a stream on the edge of Penestanan village. It makes its own organic skincare from garden-sourced ingredients and uses it for massages, facials, scrubs and outdoor flower baths. A garden tour is also an option.') = '5b15b3ded847a0b52009f936b0d68b5d'),
  (34, 'cantika-zest', 'best_for', (select count(*)::int from venues where slug = 'cantika-zest' and status = 'active' and publication_status = 'published' and md5(best_for) = '1499c7b6740d7fcc64144d27ad45edd1'), md5('A treatment with natural, organic products in a quiet Penestanan garden') = 'a72a5aa7e15fca9f17f83ceb0140228e'),
