  (36, 'casa-luna', 'best_for', (select count(*)::int from venues where slug = 'casa-luna' and status = 'active' and publication_status = 'published' and md5(best_for) = 'f8ec45d6dfa79099ce0ed9ea9ea2dec0'), md5('A Balinese meal in central Ubud, from breakfast through to dinner') = 'c4735a9acea2d1d17597801b2c08413d'),
  (37, 'casa-luna', 'not_for', (select count(*)::int from venues where slug = 'casa-luna' and status = 'active' and publication_status = 'published' and md5(not_for) = '8d48bfe1c08de31796eef6ab92021397'), md5('A meal at street-warung prices, because this is a mid-range destination restaurant') = '58746eee8e2d07b4d0c191cb2b5a75a2'),
  (38, 'cascades', 'why_its_here', (select count(*)::int from venues where slug = 'cascades' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '60050fbf5de3319fcd6a12b422b9cbab'), md5('Viceroy Bali''s restaurant, also branded as part of CasCades Suites, sits above the Valley of the Kings with jungle views. Central Ubud is about five minutes'' drive away. The kitchen does a Balinese Rijsttafel tasting menu and Western dishes, with produce from its own organic gardens.') = '5ca84979b14efd347129e740fe9b7520'),
  (39, 'cascades', 'best_for', (select count(*)::int from venues where slug = 'cascades' and status = 'active' and publication_status = 'published' and md5(best_for) = '5f9815d86a45c400e8e3159d31391e09'), md5('Couples or a small group sitting down to the Indonesian tasting menu with a valley view') = 'f3e7f313bcbd8822bd8b0a4ba2b03bcb'),
  (40, 'cascades', 'not_for', (select count(*)::int from venues where slug = 'cascades' and status = 'active' and publication_status = 'published' and md5(not_for) = '49b841ebbcbb2f9da9932add7536399c'), md5('Budget diners, or anyone without their own transport hoping to walk in from central Ubud: it is a five-minute drive out') = '4c9532dec1883e343b67fa40a816992c'),
  (41, 'clear-cafe', 'why_its_here', (select count(*)::int from venues where slug = 'clear-cafe' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '38bd1c5e88cb36d2965b6d09240fdcdd'), md5(U&'Healthy, international food with a wellness focus, at a caf\00E9 on Jl. Hanoman in central Ubud.') = '097f5621984d9ecb312c67f2ba95a9c3'),
  (42, 'clear-cafe', 'best_for', (select count(*)::int from venues where slug = 'clear-cafe' and status = 'active' and publication_status = 'published' and md5(best_for) = 'aae6986b36955041220ebe249f2fca9e'), md5(U&'A healthy, casual meal or time at a caf\00E9 table') = '3c07ec23c705c3aa53b469537c12f45d'),
  (43, 'clear-cafe', 'not_for', (select count(*)::int from venues where slug = 'clear-cafe' and status = 'active' and publication_status = 'published' and md5(not_for) = '9e3a9ab4083910baaf2127b88f1ab174'), md5(U&'Formal fine dining. This is a casual caf\00E9') = '042975bc61c95934ad9e92a9e6d6d8dd'),
  (44, 'coco-nails-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'coco-nails-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '59cf6bdfc84ba42a684dd72a1646eb05'), md5('Manicures, pedicures and nail art at an Ubud nail salon in a central location.') = 'e111d438194a2b4a47186b1e96f4ffbf'),
  (45, 'coco-nails-ubud', 'best_for', (select count(*)::int from venues where slug = 'coco-nails-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = '6d0605853b4f9f1d418b071f30ff73f0'), md5(U&'A quick mani-pedi between Ubud''s shops and caf\00E9s') = 'aa4086c4cafecfd2d03fd277fd6a4f27'),
  (46, 'como-shambhala-at-como-uma-ubud-yoga-ubud', 'best_for', (select count(*)::int from venues where slug = 'como-shambhala-at-como-uma-ubud-yoga-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = '0690d75918a0074d0d55f5b6e8e3909e'), md5('A resort yoga class above the valley, for guests and visitors alike') = 'b745b2d5a9f6ef4103212b387f9928c2'),
  (47, 'como-uma-ubud-fitness', 'why_its_here', (select count(*)::int from venues where slug = 'como-uma-ubud-fitness' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '9aba2dd89bab9c4001a57cf7b53b11ba'), md5('COMO Uma Ubud''s fitness centre has current cardio and strength machines, with the COMO Shambhala wellness programme behind it. A resident instructor builds private sessions for any level. In the same wellness area are an open-air yoga pavilion, steam rooms and a 25-metre pool.') = 'b2fa68f9a245a6598d9cdf664bdcee05'),
  (48, 'como-uma-ubud-fitness', 'best_for', (select count(*)::int from venues where slug = 'como-uma-ubud-fitness' and status = 'active' and publication_status = 'published' and md5(best_for) = '0c4f281d7e0fed5401d79e18b6d4171e'), md5('Guests in Ubud who want machine-based training with a resident instructor, alongside a jungle-facing yoga pavilion') = '7d29ccb1bb9b050e046d2f9394d1623c'),
  (49, 'dala-spa-beauty-at-alaya-ubud-ubud', 'best_for', (select count(*)::int from venues where slug = 'dala-spa-beauty-at-alaya-ubud-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = 'd0d84cb7939b9bef70aaf78e18b78483'), md5('A salon or beauty treatment added to a spa day at the resort') = '812c9c58940a98b433a2fc87f91571fe'),
  (50, 'dicarik-warung', 'why_its_here', (select count(*)::int from venues where slug = 'dicarik-warung' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c363aba6f6960e2df012fdf04bcbf0af'), md5(U&'A warung on Jl. Kajeng, on the rice-field walk north of central Ubud, run by a mother-daughter team. The hands-on Balinese cooking class teaches the garden spices, then 7 dishes and 2 drinks. There is \00E0 la carte Balinese food too, such as betutu bebek.') = 'b492ab37c7c609208260061556b8cf64'),
  (51, 'dicarik-warung', 'best_for', (select count(*)::int from venues where slug = 'dicarik-warung' and status = 'active' and publication_status = 'published' and md5(best_for) = '49788aedd100a657edcff8f013c882eb'), md5('A hands-on Balinese cooking class among the rice fields, or betutu bebek ordered ahead') = 'af9c2dc15956a9c76ed34e5be71c8a6d'),
  (52, 'dicarik-warung', 'not_for', (select count(*)::int from venues where slug = 'dicarik-warung' and status = 'active' and publication_status = 'published' and md5(not_for) = '0af65193fba0baaebfba0c11e2eb3ec0'), md5(U&'A walk-in \00E0 la carte meal, because dishes like betutu bebek are ordered in advance') = '96d0cc1cfb446d8342c0db42e91e1c4c'),
  (53, 'donna-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'donna-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '7aa63e84068c9cb21cdc5cbac04cb961'), md5('In the middle of Jalan Monkey Forest, Donna is a restaurant, lounge and rooftop bar with a Mediterranean and Latin American menu. It opens daily from late morning until late. Shisha is served after 4pm, and the upstairs becomes a club on Friday nights.') = '0ea3a34f98391f8cf261ecf430388caf'),
  (54, 'donna-ubud', 'best_for', (select count(*)::int from venues where slug = 'donna-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e6c8fd53b8092268c660a3343954e684'), md5('Groups or couples after dinner and cocktails that turn into a lively night out in central Ubud') = 'fa4d4695a90e49a6322fc999dc1d9d99'),
  (55, 'donna-ubud', 'not_for', (select count(*)::int from venues where slug = 'donna-ubud' and status = 'active' and publication_status = 'published' and md5(not_for) = 'fc0d032db6bfcd9ec15cdcf3408ee3ff'), md5('A quiet, early, low-key dinner: on Friday nights the venue turns into a nightclub') = 'd1c501f83d74cfffd9446c2b1605e055'),
  (56, 'four-seasons-resort-bali-at-sayan-fitness', 'why_its_here', (select count(*)::int from venues where slug = 'four-seasons-resort-bali-at-sayan-fitness' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '41066a625bb6be5a14016d1980ca24ed'), md5('The Fitness Hub at Four Seasons Sayan, high above the Ayung River, is free for resort guests. Beyond the gym there are three private studios with trainers and a reformer pilates studio. The recovery room has an ice bath, a sauna and a steam room.') = 'dce3bcfd17c83ac3c3cc0ebb2d5f018d'),
  (57, 'four-seasons-resort-bali-at-sayan-fitness', 'best_for', (select count(*)::int from venues where slug = 'four-seasons-resort-bali-at-sayan-fitness' and status = 'active' and publication_status = 'published' and md5(best_for) = '9004af8088978cd4b4ca7cf19b014c44'), md5('Guests who want a full training and recovery set-up, from reformer pilates to an ice bath, without leaving the resort') = '023c908a05954a5767d8627324ba902e'),
  (58, 'gajah-putih-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'gajah-putih-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c2f8b2f88f0913f7da8dd8969e3c1c21'), md5('An Ubud restaurant whose cooking is billed as modern gourmet cuisine. Its published menu lists 8 priced items, including alcohol, non-alcohol and wine pairings; Pairing Wine Malam is 400K IDR. Booking is on the restaurant''s own website.') = '75199e34c86eb56a38536b680a47df1b'),
  (59, 'gajah-putih-ubud', 'best_for', (select count(*)::int from venues where slug = 'gajah-putih-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = '148e87d88a591d316d8ccf870ce9635d'), md5('A special-occasion dinner') = '555e8face62e834ebdf21c4e9824a9b0'),
  (60, 'gajah-putih-ubud', 'not_for', (select count(*)::int from venues where slug = 'gajah-putih-ubud' and status = 'active' and publication_status = 'published' and md5(not_for) = '297f2399603edf202edad2a7cd0b41e5'), md5('A cheap casual meal') = '2aa047eb594d3522ceabbf8346ae6710'),
  (61, 'gelato-secrets-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'gelato-secrets-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'f3aabdc4441e9adb68b8d01b26e269c8'), md5('Gelato Secrets is an Italian gelato brand that opened its shop in Ubud in 2009. The gelato and sorbetto are made fresh every day from all-natural ingredients. Some flavours are Indonesian-inspired, such as black rice and coconut pandan.') = '886fda2f35a23ad0bd5278ba09da46c0'),
  (62, 'gelato-secrets-ubud', 'best_for', (select count(*)::int from venues where slug = 'gelato-secrets-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = '29440ac6c8a9fde11849a6f807a2350d'), md5('A cool-down dessert after sightseeing, for families and everyone else, for example near Monkey Forest or Jalan Raya Ubud') = 'd1dc70fea513c6b54fd7532c4bef873d'),
  (63, 'heart-space-bali', 'why_its_here', (select count(*)::int from venues where slug = 'heart-space-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '0bfc674cb8b6b47ced2efde013aa3650'), md5('A calm, holistic studio on the corner where Pengosekan meets Nyuh Kuning. It specialises in slower, restorative practice, sound and Balinese healing.') = '4524f989bc25741d47eeb17c7c8df675'),
  (64, 'heart-space-bali', 'best_for', (select count(*)::int from venues where slug = 'heart-space-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '8d9e0365cf9fee8f4ba6a74fbf293def'), md5('Gentle Yin and restorative yoga, sound baths, or a cacao or healing ceremony') = 'b1a3563af71fda26cf0411ec93b412c1'),
  (65, 'heart-space-bali', 'not_for', (select count(*)::int from venues where slug = 'heart-space-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = '09c8ca3106a2a0271fff9aaacf8a3c74'), md5('A strong, athletic or heated class, because the practice here is slow and restorative') = '90de5ecbbad0ae6607e3d933b514bdad'),
  (66, 'hujan-locale', 'why_its_here', (select count(*)::int from venues where slug = 'hujan-locale' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3f750d46c9df67e7edbbf8df68b22fda'), md5('Will Meyrick''s modern Indonesian restaurant in central Ubud, in a renovated two-storey building. The bar is downstairs; upstairs, the dining room looks over a temple and the street. The kitchen reworks street-food flavours from Java, Sumatra, Sulawesi and Bali with local ingredients and modern presentation.') = 'fae12d4f6655bc18cf7577b37ae34bf6'),
  (67, 'hujan-locale', 'best_for', (select count(*)::int from venues where slug = 'hujan-locale' and status = 'active' and publication_status = 'published' and md5(best_for) = '52151667c3326b5ee8dee5970a881ac5'), md5('A dinner or shared meal of chef-driven Indonesian regional cooking') = 'a9ae6ae955411a748256a552438d2eaf'),
  (68, 'hujan-locale', 'not_for', (select count(*)::int from venues where slug = 'hujan-locale' and status = 'active' and publication_status = 'published' and md5(not_for) = 'ed7796c15050a2d730f01ab18c381a76'), md5('A cheap, no-frills warung meal: this is a chef''s restaurant') = '5d6c4906ffb1d3f5c6beeacb43149ec2'),
  (69, 'ibu-rai', 'why_its_here', (select count(*)::int from venues where slug = 'ibu-rai' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '34a8d9c8646acb78bbaa5302c2fd1613'), md5('Ibu Rai, born in 1925, ran a food stall near Ubud Palace; her family founded this restaurant and gallery on Jalan Monkey Forest. It opened as a restaurant in 1992, and Indonesian specialties share the menu with European dishes in a room full of art.') = '3ac0b9ce8aa3413874cfe2f26ecdd8a3'),
  (70, 'ibu-rai', 'best_for', (select count(*)::int from venues where slug = 'ibu-rai' and status = 'active' and publication_status = 'published' and md5(best_for) = '2703cc8a99a0427305a524fe924b1f8c'), md5('A sit-down meal in the centre of town that mixes Indonesian classics with familiar European comfort dishes') = 'ecf90065a4da5567773614471f32a1ee'),
  (71, 'ibu-rai', 'not_for', (select count(*)::int from venues where slug = 'ibu-rai' and status = 'active' and publication_status = 'published' and md5(not_for) = '945c924beae52319c46044239724eb68'), md5('A quiet, private table, because it sits on Ubud''s busy tourist strip') = '71ddd285d4a947397b9f855504670592'),
  (72, 'jaens-spa', 'why_its_here', (select count(*)::int from venues where slug = 'jaens-spa' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '1d858d309972ecdc8f3690635681ae34'), md5('A Balinese spa with several outlets near the Monkey Forest, pitched as ''affordable luxury''. The menu covers Balinese massage, facials, body care and full-day packages with free transport in the Ubud area.') = '2679a1cbdb2460bb56d8fd06b1c43b36'),
  (73, 'jaens-spa', 'best_for', (select count(*)::int from venues where slug = 'jaens-spa' and status = 'active' and publication_status = 'published' and md5(best_for) = '7cc51beca4f1a96cf536c9e6c019b36f'), md5('A polished but affordable spa day near the Monkey Forest, as a couple or on your own') = '581744d28e0b5983ced38e75efc0efaa'),
  (74, 'karsa-spa', 'why_its_here', (select count(*)::int from venues where slug = 'karsa-spa' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'e4118e706d2f7eb953b89229cacee5c9'), md5('An open-air spa in the rice fields at the end of the Campuhan Ridge Walk, founded in 2012. Massage runs from deep-tissue shiatsu to Balinese, Thai and sports styles. Reiki and chakra healing are offered too, and the oils used are organic and Ayurvedic.') = 'd007c4920c417cac5fb9af1e656365cf'),
  (75, 'karsa-spa', 'best_for', (select count(*)::int from venues where slug = 'karsa-spa' and status = 'active' and publication_status = 'published' and md5(best_for) = 'af86f6a775b72e2d72a0571e947cde3a'), md5('Walkers finishing the Campuhan Ridge Walk, or couples after an open-air massage in the rice fields away from town noise') = 'c41b89c55d534d1e0b0d3e7abf25f7fb'),
  (76, 'karsa-spa', 'not_for', (select count(*)::int from venues where slug = 'karsa-spa' and status = 'active' and publication_status = 'published' and md5(not_for) = '0811eaa7058ba7692e802159bd1a106a'), md5('A same-day walk-in from central Ubud: it is about a 30-minute walk out and books up days ahead') = '066176bdcc32ca25e715990cc2538169'),
  (77, 'kojin-teppanyaki-restaurant-ubud-by-wonderspace', 'why_its_here', (select count(*)::int from venues where slug = 'kojin-teppanyaki-restaurant-ubud-by-wonderspace' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'e94f9ccf49b90e98eabaff1b7fb5822c'), md5('Named after Kojin, a Japanese god of fire, this restaurant in Kenderan cooks teppanyaki, kaiseki and omakase at the counter. It opens for lunch and dinner.') = '27bcde4c02162083ae80008e92dd8baf'),
  (78, 'kush-ayurveda-yoga-barn', 'why_its_here', (select count(*)::int from venues where slug = 'kush-ayurveda-yoga-barn' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '08978c1dfe57dd5606a338f35fe94e4e'), md5('An Ayurvedic spa inside The Yoga Barn, where the therapists assess your dosha first and tailor the treatment to it. Abhyanga, Shirodhara, hot-stone Shila massage and Ayurvedic facials with freshly prepared botanicals are on the list.') = '1c58dd3f4bdea8175b064552fd896d1b'),
  (79, 'kush-ayurveda-yoga-barn', 'best_for', (select count(*)::int from venues where slug = 'kush-ayurveda-yoga-barn' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ba443be2789c82bebe02dc87a5caf084'), md5('Yoga Barn visitors who want Ayurvedic treatment, such as a dosha consultation or Shirodhara') = 'dfb8b8effe8ac94b65e1b486e18b4507'),
  (80, 'kush-ayurveda-yoga-barn', 'not_for', (select count(*)::int from venues where slug = 'kush-ayurveda-yoga-barn' and status = 'active' and publication_status = 'published' and md5(not_for) = 'a81cd673dc4357013a748dbd83338c89'), md5('Walk-ins, because treatments must be booked in advance') = '9a69953980ef103cdecf9ccbbce3306e'),
  (81, 'la-portal-to-shamballah', 'why_its_here', (select count(*)::int from venues where slug = 'la-portal-to-shamballah' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ef40ab4ee81ec053a2db2d8f41ddbac6'), md5('A vegetarian restaurant and events space in Peliatan, cooking Arabian, Indonesian and Asian dishes with vegan and gluten-free options. The bread is homemade, and the menu runs to Euro-Arabia fusion plates and quesadillas. It also hosts live music and workshops and has private healing rooms.') = 'c0945c96f8609f1d1fd0fed6b18fabd8'),
  (82, 'laka-leke', 'why_its_here', (select count(*)::int from venues where slug = 'laka-leke' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '5b88d70398eb6d0f79ca18d026ff799f'), md5('Cafe Wayan & Bakery''s sister restaurant, in a garden by the rice fields near Nyuh Kuning and the Monkey Forest. Private dining is in tree-shaded pavilions; craft workshops run in the afternoon. Scheduled evenings bring a Balinese dance show (Kecak/Fire Dance) and a group buffet.') = '9f106ac3dc541f41c03399c52c02cd6e'),
  (83, 'laka-leke', 'best_for', (select count(*)::int from venues where slug = 'laka-leke' and status = 'active' and publication_status = 'published' and md5(best_for) = '4112cb0242a7ad1e34e5820e6ec053e7'), md5('Groups after a garden dinner with a Balinese cultural show, or a meal in a private pavilion') = 'b59ba1cfa5cd8de86c1cb337c52539c6'),
  (84, 'laka-leke', 'not_for', (select count(*)::int from venues where slug = 'laka-leke' and status = 'active' and publication_status = 'published' and md5(not_for) = 'ee7eb823325445a714f57b338193c07e'), md5('Solo diners or a quick, casual walk-in meal: set evenings centre on a dance show and a group buffet') = 'c03abe723d9bb0f56295a2f3c6a756d1'),
  (85, 'locavore-nxt', 'why_its_here', (select count(*)::int from venues where slug = 'locavore-nxt' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'ab7c326f3f83e3b4bbf4b20f4c2c123c'), md5('The more experimental, ingredient-driven sibling of Locavore, opened in Lodtunduh in December 2023 and led by chefs Eelke Plasmeijer and Ray Adriansyah. This 30-seat tasting-menu room uses only local Indonesian ingredients, cooked with modern European technique.') = '615dfd49385bc367543d5f50ef465518'),
  (86, 'locavore-nxt', 'best_for', (select count(*)::int from venues where slug = 'locavore-nxt' and status = 'active' and publication_status = 'published' and md5(best_for) = '7b76f08f547e298f7da956debfa080e7'), md5('A booked, multi-course tasting menu built on the work of Indonesian farmers, fishers and producers') = '5f900a13b1b8da833b0adf60f9aa7efc'),
  (87, 'locavore-nxt', 'not_for', (select count(*)::int from venues where slug = 'locavore-nxt' and status = 'active' and publication_status = 'published' and md5(not_for) = '7967897cfb6944f3033106bf42b4aaaa'), md5('A quick, low-key or budget meal, or walking in: it is a multi-course tasting menu by reservation only') = 'da5964d13f848b4688e31735fc1d7ac1'),
  (88, 'mandapa-spa-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'mandapa-spa-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '260d531f7c4144394b8bb60b2685679b'), md5('The riverside spa at Mandapa, a Ritz-Carlton Reserve on the Ayung river in Kedewatan.') = '19d1755c6ef5ad786379b7b1852e2621'),
  (89, 'mandapa-spa-ubud', 'best_for', (select count(*)::int from venues where slug = 'mandapa-spa-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b24c8fbeca276157fb045170020a3e31'), md5('An ultra-luxury spa visit by the Ayung river') = '071b8766590b52f9b69ec0a9b7211e5b'),
  (90, 'mango-tree-spa-loccitane', 'why_its_here', (select count(*)::int from venues where slug = 'mango-tree-spa-loccitane' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a6e7894a42b7d742a2e7ed2c4f4f3d34'), md5('A luxury spa at Kupu Kupu Barong Villas in the Ayung River valley, with treatment rooms built into a giant mango tree. The rituals use L''OCCITANE products, and there is a steam room.') = '5533f0df4d31c465832b1e5f024b262e'),
  (91, 'mango-tree-spa-loccitane', 'best_for', (select count(*)::int from venues where slug = 'mango-tree-spa-loccitane' and status = 'active' and publication_status = 'published' and md5(best_for) = '3b36ade3369dd668dc58263a41d423f2'), md5('A splurge or a romantic spa day, with river-valley views and L''OCCITANE rituals') = '4cda381d7e52509a78dc5beabf38e2b2'),
  (92, 'mango-tree-spa-loccitane', 'not_for', (select count(*)::int from venues where slug = 'mango-tree-spa-loccitane' and status = 'active' and publication_status = 'published' and md5(not_for) = 'ab6132b2a712c2e80814b3bc7a7cbf00'), md5(U&'A budget treatment or a walk-in from the centre of town \2014 it is a luxury spa out in the Ayung valley') = '668c63ee96bdbc4ff8159ceb39cf0e8c'),
  (93, 'maya-ubud-spa-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'maya-ubud-spa-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '3047700918cc2872d5b876ba46248d54'), md5('The wellness side of Maya Ubud Resort & Spa, on the Peliatan ridge. Its riverside spa has treatment pavilions down in the Petanu valley. A yoga shala and a fitness centre look out over the same valley.') = '54b6b08f9cd7a6f95ca94f79f1ad50ae'),
  (94, 'maya-ubud-spa-ubud', 'best_for', (select count(*)::int from venues where slug = 'maya-ubud-spa-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = 'ccc25059bf5a96194d59724dcabb31a0'), md5('A resort spa treatment, yoga class or gym session away from the bustle of central Ubud') = '96f486d7a329cc4302f3c9c96b4aa36c'),
  (95, 'melting-wok-warung', 'why_its_here', (select count(*)::int from venues where slug = 'melting-wok-warung' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'de68e36278ca7cff895f9a19ce12fe0e'), md5('A French-Laotian couple runs this tiny eight-table warung on Jl. Gootama. The blackboard menu is short and changes daily: coconut curries, stir-fries and crepes. The cooking uses Laotian herbs, and the desserts have French touches.') = 'c961f0b1ecf1b484a44cf139d9d54ac8'),
  (96, 'melting-wok-warung', 'best_for', (select count(*)::int from venues where slug = 'melting-wok-warung' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b45ccef1e92643b86091b5f3a47b9268'), md5('An intimate dinner of herb-forward coconut curries and French-Laotian flavours') = '77f36f07e317540089620a6ebfcea194'),
  (97, 'melting-wok-warung', 'not_for', (select count(*)::int from venues where slug = 'melting-wok-warung' and status = 'active' and publication_status = 'published' and md5(not_for) = 'ac44f30e723a9a3e2915fa09e60ec115'), md5('Large groups or walk-ins without a booking: there are eight tables and a short menu') = '00d598e1810ae8b53c32afddaff60fc6'),
  (98, 'milk-and-madu-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'milk-and-madu-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'a5b9410f8c4bbd46b3bd4596d05ed71c'), md5('An all-day cafe on Jl. Suweta with a kids menu and group bookings for up to 20. There is a 110K breakfast set.') = 'b4925fd12dec6dabf90642da035628ec'),
  (99, 'milk-and-madu-ubud', 'best_for', (select count(*)::int from venues where slug = 'milk-and-madu-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = '41936b45e013707d93269c6bb7f90c1a'), md5('Families with children, a mixed group, a central place to meet, or anyone who wants a fixed breakfast') = '3bd36e1d990c23803c30aed9f8206828'),
  (100, 'moksa', 'why_its_here', (select count(*)::int from venues where slug = 'moksa' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '258a1042f9c67b49f2fd605044864497'), md5('A plant-based restaurant in Sayan with a permaculture garden and a farm-to-table kitchen.') = 'a07d77c26d4e8199402f72f1072ea33c'),
  (101, 'moksa', 'best_for', (select count(*)::int from venues where slug = 'moksa' and status = 'active' and publication_status = 'published' and md5(best_for) = '9d70873af79c1ca82aebffa8ec56083a'), md5('Plant-based diners making a trip of it for a meal in the garden') = 'a708fdf6fecb889ad375823bdaff6092'),
  (102, 'moksa', 'not_for', (select count(*)::int from venues where slug = 'moksa' and status = 'active' and publication_status = 'published' and md5(not_for) = 'cdddf4e2465297e75e5d582233e0a0a1'), md5('A meat-heavy meal or a night out in central Ubud: the menu is plant-based and it is out in Sayan') = '75ca89d100e6f63e3e4c71fef7552cf1'),
  (103, 'monkey-bar-bali', 'why_its_here', (select count(*)::int from venues where slug = 'monkey-bar-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '89668501b2be6ebd3044e25984ed0ef2'), md5('Up in the hills of East Bali, this restaurant and bar is built around an infinity pool at Bella Kita Mountain Retreat. Valley views run toward the sea, and produce comes from the property''s own farm. Entry is pay-and-swim, and it includes credit toward food.') = 'd27d4b79de0d57cd1f2fd5ddd9078d93'),
  (104, 'monkey-bar-bali', 'best_for', (select count(*)::int from venues where slug = 'monkey-bar-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '696e3bc99f16f493e993fa65003b311d'), md5('A swim and lunch on an East Bali day trip, away from the southern crowds') = 'd6de7bfe21e83c7b4373632cf086c6d6'),
  (105, 'mozaic', 'why_its_here', (select count(*)::int from venues where slug = 'mozaic' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c097b16fcbc77922e48e72e087f1d36d'), md5('Chef Chris Salans founded this Kedewatan fine-dining restaurant; head chef and co-owner Blake Thornley now leads the kitchen. The cooking applies French technique to Indonesian and Balinese ingredients. There is a multi-course tasting menu and, separately, a Chef''s Table at the live kitchen.') = '313e4e91128b8d1de5a6e4739f39645a'),
  (106, 'mozaic', 'best_for', (select count(*)::int from venues where slug = 'mozaic' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c032e5a48eadbe88b7a20f3ba67e01a2'), md5('A special occasion marked with a French-Balinese tasting menu in a garden') = 'fe13dd07daeb68236670e6c94583267a'),
  (107, 'mozaic', 'not_for', (select count(*)::int from venues where slug = 'mozaic' and status = 'active' and publication_status = 'published' and md5(not_for) = '48a0f0da4d6e10eced0d02a562887b47'), md5('A quick, casual meal or a tight daily budget, because the format is a multi-course tasting menu') = 'a9044acdd4d139af96454d48408eb4fa'),
