  (130, 'room4dessert', 'best_for', (select count(*)::int from venues where slug = 'room4dessert' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b3e79d61403668be3404da47626b74ef'), md5('Pastry enthusiasts, or a special occasion built around a multi-course dessert tasting') = '29a6e4534d070843ca7d19cff9701180'),
