  (138, 'sawobali', 'best_for', (select count(*)::int from venues where slug = 'sawobali' and status = 'active' and publication_status = 'published' and md5(best_for) = 'a4e31b5055240bf2381d506df7d4effd'), md5('A budget home-style lunch buffet for vegans, vegetarians or anyone avoiding garlic and onion') = '638c319d40602806353d08494f4942f2'),
