  (141, 'sayuri-healing-food', 'best_for', (select count(*)::int from venues where slug = 'sayuri-healing-food' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b2d22206e73c0b2c6c0c8fdf11761964'), md5('A long daytime cafe sit over raw, plant-based food') = '26e502af8fb6cd3e3d5687cf7c9bfcd8'),
