  (145, 'seeds-of-life', 'best_for', (select count(*)::int from venues where slug = 'seeds-of-life' and status = 'active' and publication_status = 'published' and md5(best_for) = 'e07338e033aec78b4dcbc6596c26b183'), md5('A calm plant-based meal in central Ubud, for raw-food eaters and anyone into yoga') = '4afbc8e4a7c9cea669ee255312730a22'),
