  (163, 'taksu-yoga-ubud', 'best_for', (select count(*)::int from venues where slug = 'taksu-yoga-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = '340001050612a1feb17efc650319c0d9'), md5('An intimate, personalised yoga class paired with a massage or spa treatment in the same visit') = '73c9b0b86e657acc832c1ff0ab4ec79d'),
  (164, 'the-elephant', 'why_its_here', (select count(*)::int from venues where slug = 'the-elephant' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'c3ed6b12a00d1ef677bf6b61f5a43aae'), md5('The Elephant is an open-air, 100% vegetarian and vegan restaurant on Jl. Raya Sanggingan. Its elevated terrace looks over Campuhan Ridge, and it serves all day from breakfast through dinner. The sourcing is organic and local, along slow-food lines.') = 'cc66cc1f7177b59aa2ccb720bba319fe'),
  (165, 'the-elephant', 'best_for', (select count(*)::int from venues where slug = 'the-elephant' and status = 'active' and publication_status = 'published' and md5(best_for) = 'dd56d725dd4c38b311dbbfb95ed2c2e8'), md5('Vegetarians and vegans after a meal looking over Campuhan Ridge') = '9d4591ad8c6100db91185e9db08f0b21'),
  (166, 'the-elephant', 'not_for', (select count(*)::int from venues where slug = 'the-elephant' and status = 'active' and publication_status = 'published' and md5(not_for) = 'fecb980b3cb2e9722a38c77848fa3407'), md5('Meat or seafood, because the whole menu is vegetarian and vegan') = '3b2796e8bc51da575595f179b74272d4'),
