  (168, 'the-shala-bali', 'best_for', (select count(*)::int from venues where slug = 'the-shala-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '5020037873a562dc2033db9e41c15b2b'), md5('A stay built around daily practice and Ayurvedic treatments') = '20572d9a6a47b65e27a544a67fb499ec'),
  (169, 'the-shala-bali', 'not_for', (select count(*)::int from venues where slug = 'the-shala-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = '5f41d36e1fb879297fe23692d0795702'), md5('A single drop-in class: the place is set up for staying and practising') = '3421353489999259cc21d6136cb54e62'),
